                holysite_adj = calculate_full_adjacency('HOLY_SITE', holysite_tile,
                                                         district_tiles - {holysite_tile}, city_center)
                commercial_adj = calculate_full_adjacency('COMMERCIAL_HUB', commercial_tile,
                                                           district_tiles - {commercial_tile}, city_center)

                total = campus_adj + holysite_adj + commercial_adj

                if total > best_total:
                    best_total = total
                    best_config = {
                        'city_center': city_center,
                        'CAMPUS': campus_tile,
                        'HOLY_SITE': holysite_tile,
