    ('CAMPUS', 'HOLY_SITE', 'COMMERCIAL_HUB'),
    ('CAMPUS', 'HOLY_SITE', 'INDUSTRIAL_ZONE'),
    ('CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE'),
    ('CAMPUS', 'COMMERCIAL_HUB', 'THEATER_SQUARE'),
]

for d1, d2, d3 in district_options:
    # Get candidate tiles for each
    def get_candidates(dtype):
        if dtype == 'CAMPUS':
            return campus_candidates
        elif dtype == 'HOLY_SITE':
            return holysite_candidates
        elif dtype == 'COMMERCIAL_HUB':
            return commercial_candidates
        else:
            return list(buildable_tiles)[:20]  # Just sample for others

    cands1 = get_candidates(d1)
    cands2 = get_candidates(d2)
    cands3 = get_candidates(d3)

    local_best = 0
    local_config = None

    for city_center in buildable_tiles:
        for t1 in cands1:
            if t1 == city_center or t1 not in buildable_tiles:
                continue
            for t2 in cands2:
                if t2 in [city_center, t1] or t2 not in buildable_tiles:
                    continue
                for t3 in cands3:
                    if t3 in [city_center, t1, t2] or t3 not in buildable_tiles:
                        continue

                    district_tiles = {t1, t2, t3}

                    adj1 = calculate_full_adjacency(d1, t1, district_tiles - {t1}, city_center)
                    adj2 = calculate_full_adjacency(d2, t2, district_tiles - {t2}, city_center)
                    adj3 = calculate_full_adjacency(d3, t3, district_tiles - {t3}, city_center)

                    total = adj1 + adj2 + adj3

                    if total > local_best:
                        local_best = total
                        local_config = {
                            'city_center': city_center,
                            d1: t1, d2: t2, d3: t3,
                            'bonuses': {d1: adj1, d2: adj2, d3: adj3},
                            'total': total
                        }

    print(f"\n{d1} + {d2} + {d3}: best total = {local_best}")
    if local_config:
        print(f"  City: {id_to_xy(local_config['city_center'])}")
        print(f"  {d1}: {id_to_xy(local_config[d1])}, bonus={local_config['bonuses'][d1]}")
        print(f"  {d2}: {id_to_xy(local_config[d2])}, bonus={local_config['bonuses'][d2]}")
        print(f"  {d3}: {id_to_xy(local_config[d3])}, bonus={local_config['bonuses'][d3]}")
